package com.hostelmanagement.config;
import com.hostelmanagement.entity.*; import com.hostelmanagement.repository.*; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.*; import org.springframework.security.crypto.password.PasswordEncoder; import java.time.*; import java.util.List;
@Configuration public class DataSeeder { @Bean CommandLineRunner seed(UserRepository users,FloorRepository floors,RoomRepository rooms,BedRepository beds,ResidentRepository residents,RentRecordRepository rent,PasswordEncoder encoder){return args->{if(users.count()>0)return; users.save(new User("admin@hostel.in",encoder.encode("admin123"))); for(int i=1;i<=3;i++){Floor f=floors.save(new Floor(i,"Floor "+i,"Comfortable rooms on floor "+i)); for(int j=1;j<=4;j++){Room r=rooms.save(new Room((i*100+j)+"",f,4,8000,12000,"Four Sharing","Bright, ventilated room")); for(int k=1;k<=4;k++)beds.save(new Bed(k,r));}} List<Bed> all=beds.findAll(); String[] names={"Rahul Kumar","Priya Sharma","Arjun Mehta","Ananya Singh","Vikram Rao","Neha Patel","Karan Joshi","Isha Verma","Rohan Das","Meera Nair"}; for(int i=0;i<names.length;i++){Resident r=residents.save(new Resident(names[i],"98"+String.format("%08d",i+10000000),names[i].toLowerCase().replace(" ",".")+"@mail.com",8000)); if(i<8){r.setBed(all.get(i));r.setStatus(ResidentStatus.ACTIVE);all.get(i).setStatus(BedStatus.OCCUPIED);residents.save(r);beds.save(all.get(i));} RentRecord rr=new RentRecord();rr.setResident(r);rr.setBillingMonth(YearMonth.now().toString());rr.setRentAmount(8000);rr.setAmountPaid(i%3==0?8000:i%3==1?4000:0);rr.setDueDate(LocalDate.now().withDayOfMonth(5));rr.setStatus(rr.getAmountPaid()==8000?PaymentStatus.PAID:rr.getAmountPaid()>0?PaymentStatus.PARTIALLY_PAID:PaymentStatus.OVERDUE);rent.save(rr);}};}}
